CREATE TYPE "SurveyImportStatus" AS ENUM ('PROCESSING','COMPLETED','FAILED');
CREATE TYPE "SurveyMappingStatus" AS ENUM ('MAPPED','UNMAPPED');
CREATE TYPE "IntelligenceCategory" AS ENUM ('PUBLIC_PRIORITIES','ECONOMIC_CONDITIONS','GOVERNMENT_PERFORMANCE','INSTITUTIONAL_TRUST','DEMOCRACY','GOVERNANCE','CORRUPTION','PUBLIC_SERVICES','SECURITY','CIVIC_PARTICIPATION','UNMAPPED');
CREATE TABLE "data_sources" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"slug" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"source_type" TEXT NOT NULL,"attribution" TEXT NOT NULL,"source_url" TEXT,"license" TEXT,"is_public" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "survey_imports" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"data_source_id" UUID NOT NULL,"import_version" TEXT NOT NULL,"survey_round" TEXT NOT NULL,"source_file" TEXT NOT NULL,"source_sha256" TEXT NOT NULL UNIQUE,"dictionary_file" TEXT NOT NULL,"dictionary_sha256" TEXT NOT NULL,"status" "SurveyImportStatus" NOT NULL DEFAULT 'PROCESSING',"rows_inspected" INTEGER NOT NULL DEFAULT 0,"rows_imported" INTEGER NOT NULL DEFAULT 0,"rejected_rows" INTEGER NOT NULL DEFAULT 0,"warnings" JSONB NOT NULL,"weighting_fields" JSONB NOT NULL,"weighting_validation" JSONB NOT NULL,"transformation_history" JSONB NOT NULL,"started_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completed_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("data_source_id") REFERENCES "data_sources"("id") ON DELETE RESTRICT,UNIQUE("data_source_id","import_version"));
CREATE INDEX "survey_imports_source_round_status_idx" ON "survey_imports"("data_source_id","survey_round","status");
CREATE TABLE "survey_questions" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"data_source_id" UUID NOT NULL,"survey_import_id" UUID NOT NULL,"survey_round" TEXT NOT NULL,"question_code" TEXT NOT NULL,"question_text" TEXT,"dictionary_category" TEXT NOT NULL,"dictionary_note" TEXT,"mapping_status" "SurveyMappingStatus" NOT NULL DEFAULT 'UNMAPPED',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("data_source_id") REFERENCES "data_sources"("id") ON DELETE RESTRICT,FOREIGN KEY("survey_import_id") REFERENCES "survey_imports"("id") ON DELETE CASCADE,UNIQUE("survey_import_id","question_code"));
CREATE INDEX "survey_questions_mapping_idx" ON "survey_questions"("data_source_id","survey_round","mapping_status");
CREATE TABLE "survey_countries" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"survey_import_id" UUID NOT NULL,"source_code" TEXT NOT NULL,"country_name" TEXT NOT NULL,"mapping_status" "SurveyMappingStatus" NOT NULL DEFAULT 'UNMAPPED',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("survey_import_id") REFERENCES "survey_imports"("id") ON DELETE CASCADE,UNIQUE("survey_import_id","source_code"));
CREATE TABLE "survey_regions" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"survey_country_id" UUID NOT NULL,"source_code" TEXT NOT NULL,"region_name" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("survey_country_id") REFERENCES "survey_countries"("id") ON DELETE CASCADE,UNIQUE("survey_country_id","source_code"));
CREATE TABLE "survey_indicator_definitions" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"data_source_id" UUID NOT NULL,"indicator_code" TEXT NOT NULL UNIQUE,"indicator_name" TEXT NOT NULL,"category" "IntelligenceCategory" NOT NULL,"question_code" TEXT NOT NULL,"survey_round" TEXT NOT NULL,"response_mapping" JSONB NOT NULL,"mapping_version" TEXT NOT NULL,"is_active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("data_source_id") REFERENCES "data_sources"("id") ON DELETE RESTRICT);
CREATE INDEX "survey_indicator_definitions_category_idx" ON "survey_indicator_definitions"("data_source_id","category","is_active");
CREATE TABLE "survey_indicator_values" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"survey_import_id" UUID NOT NULL,"indicator_definition_id" UUID NOT NULL,"survey_country_id" UUID NOT NULL,"response_code" TEXT NOT NULL,"weighted_count" DECIMAL(20,8) NOT NULL,"total_weight" DECIMAL(20,8) NOT NULL,"unweighted_count" INTEGER NOT NULL,"weight_field" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("survey_import_id") REFERENCES "survey_imports"("id") ON DELETE CASCADE,FOREIGN KEY("indicator_definition_id") REFERENCES "survey_indicator_definitions"("id") ON DELETE RESTRICT,FOREIGN KEY("survey_country_id") REFERENCES "survey_countries"("id") ON DELETE CASCADE,UNIQUE("survey_import_id","indicator_definition_id","survey_country_id","response_code"));
CREATE INDEX "survey_indicator_values_import_country_idx" ON "survey_indicator_values"("survey_import_id","survey_country_id");
CREATE TABLE "survey_aggregate_results" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"survey_import_id" UUID NOT NULL,"indicator_definition_id" UUID NOT NULL,"survey_country_id" UUID NOT NULL,"response_code" TEXT NOT NULL,"weighted_percentage" DECIMAL(8,4),"unweighted_sample_size" INTEGER NOT NULL,"minimum_sample_size" INTEGER NOT NULL,"is_suppressed" BOOLEAN NOT NULL DEFAULT false,"suppression_reason" TEXT,"weight_field" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("survey_import_id") REFERENCES "survey_imports"("id") ON DELETE CASCADE,FOREIGN KEY("indicator_definition_id") REFERENCES "survey_indicator_definitions"("id") ON DELETE RESTRICT,FOREIGN KEY("survey_country_id") REFERENCES "survey_countries"("id") ON DELETE CASCADE,UNIQUE("survey_import_id","indicator_definition_id","survey_country_id","response_code"));
CREATE INDEX "survey_aggregate_results_safeguard_idx" ON "survey_aggregate_results"("survey_country_id","is_suppressed","unweighted_sample_size");
